// Validate and sanitize user signup data
const signup = $input.first().json.body || $input.first().json;

if (!signup.name || !signup.email) {
  throw new Error('Missing required fields: name, email');
}

// Validate email
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!emailRegex.test(signup.email)) {
  throw new Error('Invalid email format');
}

// Generate campaign ID
const campaignId = `WELCOME-${Date.now().toString().slice(-10)}`;

const sanitized = {
  campaign_id: campaignId,
  name: signup.name.trim().replace(/<[^>]*>/g, ''),
  email: signup.email.toLowerCase().trim(),
  signup_source: signup.signup_source || 'Website',
  signup_date: new Date().toISOString(),
  timezone: 'Asia/Ho_Chi_Minh',
  emails_sent: [],
  emails_opened: [],
  next_email_sequence: 1
};

console.log(`Campaign ${campaignId} started for ${sanitized.name} (${sanitized.email})`);

return [{ json: sanitized }];

